/**
 * In-memory Windows-compatible PKZIP archive generator for the entire ChargeShare project.
 */

const PROJECT_ZIP_BASE64 = "";

export function downloadProjectZip(): void {
  const binaryString = window.atob(PROJECT_ZIP_BASE64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }

  const blob = new Blob([bytes], { type: "application/zip" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = "chargeshare-project.zip";
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  window.setTimeout(() => URL.revokeObjectURL(url), 10000);
}
